import { attribute } from './attribution.js';

export function metrics(events, { from, to, campaign } = {}) {
  const clicks = events.filter((e) => e.type === 'click');
  const by = {};
  const row = (c) => (by[c] ??= { campaign: c, clicks: 0, leads: 0, sales: 0, revenue: 0 });
  for (const c of clicks) row(c.campaign).clicks++;
  for (const e of events) {
    if (e.type === 'lead') row(attribute(e, clicks)).leads++;
    if (e.type === 'sale') {
      const r = row(attribute(e, clicks));
      r.sales++;
      r.revenue += e.amount;
    }
  }
  return { campaigns: Object.values(by) };
}

