import http from 'node:http';
import { load, save } from './store.js';
import { validate } from './validate.js';
import { metrics } from './metrics.js';

function send(res, status, body) {
  res.writeHead(status, { 'content-type': 'application/json' });
  res.end(JSON.stringify(body));
}

export function createServer({ file }) {
  return http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname === '/events' && req.method === 'POST') {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      const batch = JSON.parse(raw);
      const db = await load(file);
      const accepted = [];
      const rejected = [];
      for (const [index, e] of batch.entries()) {
        const v = validate(e);
        if (v.code) {
          rejected.push({ id: e.id ?? null, index, code: v.code });
          continue;
        }
        db.events.push(v.event);
        accepted.push(e.id);
      }
      await save(file, db);
      return send(res, 200, { accepted, duplicates: [], rejected });
    }
    if (url.pathname === '/metrics') {
      const db = await load(file);
      return send(res, 200, metrics(db.events, Object.fromEntries(url.searchParams)));
    }
    send(res, 404, { error: { code: 'NOT_FOUND' } });
  });
}

