import { toMinor } from './money.js';
import { parseAt } from './time.js';

const TYPES = ['click', 'lead', 'sale'];

export function validate(e) {
  if (!e.id) return { code: 'INVALID_ID' };
  if (!TYPES.includes(e.type)) return { code: 'INVALID_TYPE' };
  const at = parseAt(e.at);
  if (at === null) return { code: 'INVALID_TIMESTAMP' };
  const event = { id: e.id, type: e.type, visitor: e.visitor, campaign: e.campaign, at };
  if (e.type === 'sale') {
    event.amount = toMinor(e.amount);
    event.currency = e.currency;
  }
  return { event };
}

