import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createServer } from '../src/server.js';

const servers = [];
after(() => { for (const s of servers) { s.closeAllConnections?.(); s.close(); } });

async function start(file = join(mkdtempSync(join(tmpdir(), 'adtrack-h-')), 'store.json')) {
  const server = createServer({ file });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  servers.push(server);
  const base = `http://127.0.0.1:${server.address().port}`;
  const call = async (method, path, body) => {
    const r = await fetch(base + path, { method, headers: { 'content-type': 'application/json' },
      body: body === undefined ? undefined : typeof body === 'string' ? body : JSON.stringify(body) });
    const text = await r.text();
    let json = null;
    try { json = JSON.parse(text); } catch { /* left null */ }
    return { status: r.status, json, type: r.headers.get('content-type') ?? '' };
  };
  const close = () => new Promise((r) => { server.closeAllConnections?.(); server.close(r); });
  return { file, post: (b) => call('POST', '/events', b), get: (p) => call('GET', p), call, close };
}

const T = (d, h = 10, m = 0, s = 0) =>
  `2026-09-${String(d).padStart(2, '0')}T${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}Z`;
const click = (id, visitor, campaign, at) => ({ id, type: 'click', visitor, campaign, at });
const lead = (id, visitor, at) => ({ id, type: 'lead', visitor, at });
const sale = (id, visitor, amount, at, currency = 'INR') => ({ id, type: 'sale', visitor, amount, currency, at });
const refund = (id, sale_id, amount, at, currency = 'INR') => ({ id, type: 'refund', sale_id, amount, currency, at });
const codes = (r) => (r.json?.rejected ?? []).map((x) => x.code);
const camp = (m, c) => m.json?.campaigns?.find((x) => x.campaign === c);

// --- events -------------------------------------------------------------------------------
test('one of each type is accepted', async () => {
  const s = await start();
  const r = await s.post([click('c1', 'v1', 'A', T(1)), lead('l1', 'v1', T(1, 11)), sale('s1', 'v1', '12.50', T(1, 12)), refund('r1', 's1', '2.50', T(1, 13))]);
  assert.equal(r.status, 200);
  assert.deepEqual(r.json, { accepted: ['c1', 'l1', 's1', 'r1'], duplicates: [], rejected: [] });
});

test('a single object is a batch of one', async () => {
  const s = await start();
  const r = await s.post(click('c1', 'v1', 'A', T(1)));
  assert.equal(r.status, 200);
  assert.deepEqual(r.json.accepted, ['c1']);
});

test('ids: the charset and the length', async () => {
  const s = await start();
  const r = await s.post([click('a b', 'v', 'A', T(1)), click('x'.repeat(65), 'v', 'A', T(1)), { type: 'click', visitor: 'v', campaign: 'A', at: T(1) }, click('ok_-1', 'v', 'A', T(1))]);
  assert.deepEqual(codes(r), ['INVALID_ID', 'INVALID_ID', 'INVALID_ID']);
  assert.deepEqual(r.json.rejected.map((x) => x.index), [0, 1, 2]);
  assert.equal(r.json.rejected[2].id, null);
  assert.deepEqual(r.json.accepted, ['ok_-1']);
});

test('an unknown type is INVALID_TYPE', async () => {
  const s = await start();
  assert.deepEqual(codes(await s.post([{ id: 'e1', type: 'view', visitor: 'v', at: T(1) }])), ['INVALID_TYPE']);
});

test('a missing field is named', async () => {
  const s = await start();
  const r = await s.post([
    { id: 'e1', type: 'click', visitor: 'v', at: T(1) },
    { id: 'e2', type: 'sale', visitor: 'v', currency: 'INR', at: T(1) },
    { id: 'e3', type: 'lead', visitor: 'v' },
    { id: 'e4', type: 'refund', amount: '1', currency: 'INR', at: T(1) },
  ]);
  assert.deepEqual(r.json.rejected.map((x) => [x.code, x.field]),
    [['MISSING_FIELD', 'campaign'], ['MISSING_FIELD', 'amount'], ['MISSING_FIELD', 'at'], ['MISSING_FIELD', 'sale_id']]);
});

test('a timestamp needs an offset', async () => {
  const s = await start();
  const r = await s.post([click('e1', 'v', 'A', '2026-09-01T10:00:00'), click('e2', 'v', 'A', '2026-09-01'),
    click('e3', 'v', 'A', 'yesterday'), click('e4', 'v', 'A', '2026-09-01T10:00:00+05:30')]);
  assert.deepEqual(codes(r), ['INVALID_TIMESTAMP', 'INVALID_TIMESTAMP', 'INVALID_TIMESTAMP']);
  assert.deepEqual(r.json.accepted, ['e4']);
});

test('amounts are exact, positive, at most two decimals', async () => {
  const s = await start();
  const bad = await s.post(['12.345', '0', '-5', '1e3', 'abc'].map((a, i) => sale(`b${i}`, 'v', a, T(1))));
  assert.deepEqual(codes(bad), Array(5).fill('INVALID_AMOUNT'));
  await s.post([sale('s1', 'v', '0.29', T(1)), sale('s2', 'v', '1.1', T(1))]);
  assert.equal(camp(await s.get('/metrics'), '(none)').revenue, 139);
});

test('a currency is three capitals, and the first sale fixes it', async () => {
  const s = await start();
  assert.deepEqual(codes(await s.post([sale('s0', 'v', '1', T(1), 'inr')])), ['INVALID_CURRENCY']);
  await s.post([sale('s1', 'v', '10', T(1), 'INR')]);
  const r = await s.post([sale('s2', 'v', '1', T(1), 'USD'), refund('r1', 's1', '1', T(2), 'USD')]);
  assert.deepEqual(codes(r), ['CURRENCY_MISMATCH', 'CURRENCY_MISMATCH']);
});

test('a refund needs its sale, and never refunds more than it', async () => {
  const s = await start();
  await s.post([sale('s1', 'v', '10', T(1))]);
  const r = await s.post([refund('r0', 'nope', '1', T(2)), refund('r1', 's1', '6', T(2)), refund('r2', 's1', '5', T(2)), refund('r3', 's1', '4', T(2))]);
  assert.deepEqual(r.json.rejected.map((x) => [x.id, x.code]), [['r0', 'UNKNOWN_SALE'], ['r2', 'REFUND_EXCEEDS_SALE']]);
  assert.deepEqual(r.json.accepted, ['r1', 'r3']);
});

test('a refund may follow its sale in the same batch', async () => {
  const s = await start();
  const r = await s.post([sale('s1', 'v', '10', T(1)), refund('r1', 's1', '3', T(2))]);
  assert.deepEqual(r.json.accepted, ['s1', 'r1']);
});

// --- batches and HTTP ---------------------------------------------------------------------
test('a bad batch is 400 BAD_BATCH', async () => {
  const s = await start();
  for (const body of [[], Array.from({ length: 101 }, (_, i) => click(`c${i}`, 'v', 'A', T(1))), '"hello"', '42']) {
    const r = await s.post(body);
    assert.equal(r.status, 400, JSON.stringify(body).slice(0, 40));
    assert.equal(r.json?.error?.code, 'BAD_BATCH');
  }
});

test('invalid JSON is 400, and the service keeps serving', async () => {
  const s = await start();
  const r = await s.post('{nope');
  assert.equal(r.status, 400);
  assert.equal(r.json?.error?.code, 'INVALID_JSON');
  assert.equal((await s.post([click('c1', 'v', 'A', T(1))])).status, 200);
});

test('a body over 64 KiB is 413, and the service keeps serving', async () => {
  const s = await start();
  const r = await s.post([click('c1', 'v', 'x'.repeat(70 * 1024), T(1))]);
  assert.equal(r.status, 413);
  assert.equal(r.json?.error?.code, 'TOO_LARGE');
  assert.equal((await s.post([click('c2', 'v', 'A', T(1))])).status, 200);
