test('all rejected is 422; mixed is 200 with the indexes', async () => {
  const s = await start();
  const all = await s.post([{ id: 'x', type: 'nope', at: T(1) }]);
  assert.equal(all.status, 422);
  assert.deepEqual(codes(all), ['INVALID_TYPE']);
  const mixed = await s.post([{ id: 'x1', type: 'nope', at: T(1) }, click('c1', 'v', 'A', T(1)), { id: 'x2', type: 'nope', at: T(1) }]);
