test('unknown paths are 404, wrong methods 405, all JSON', async () => {
  const s = await start();
  const cases = [['GET', '/events', 405, 'METHOD_NOT_ALLOWED'], ['POST', '/metrics', 405, 'METHOD_NOT_ALLOWED'], ['GET', '/nope', 404, 'NOT_FOUND']];
  for (const [method, path, status, code] of cases) {
    const r = await s.call(method, path, method === 'POST' ? [] : undefined);
    assert.equal(r.status, status, `${method} ${path}`);
    assert.equal(r.json?.error?.code, code);
    assert.match(r.type, /application\/json/);
  }
